import { View, Text, StyleSheet } from 'react-native';
import { useTheme } from '../theme';
import { colors } from '../theme/tokens';

export interface CardProps {
  title: string;
  body: string;
}

export function Card({ title, body }: CardProps): JSX.Element {
  const { isDark } = useTheme();
  const surface = isDark ? styles.darkSurface : styles.lightSurface;
  const text = isDark ? styles.darkText : styles.lightText;
  return (
    <View style={[styles.card, surface]} accessible accessibilityLabel={`${title}: ${body}`}>
      <Text style={[styles.title, text]}>{title}</Text>
      <Text style={text}>{body}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  card: { padding: 16, borderRadius: 12 },
  title: { fontSize: 18, fontWeight: '700', marginBottom: 8 },
  lightSurface: { backgroundColor: colors.surface.light },
  darkSurface: { backgroundColor: colors.surface.dark },
  lightText: { color: colors.text.light },
  darkText: { color: colors.text.dark },
});
